from fastapi import APIRouter, FastAPI, FastAPIError
import pytest

def test_include_router_self():
    router = APIRouter()
    try:
        router.include_router(router)
    except FastAPIError as exc:
        assert str(exc) == "You cannot include a router in itself."
        print("Caught expected FastAPIError")
        return
    except Exception as exc:
        pytest.fail(f"Caught unexpected exception: {type(exc).__name__}: {exc}")

    pytest.fail("Did not raise FastAPIError when including router in itself")

if __name__ == "__main__":
    try:
        test_include_router_self()
        print("Test passed!")
    except Exception as e:
        print(f"Test failed: {e}")
        exit(1)

